<?php $l=$this->getVar('liveclassLabels');$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$icons=$this->getObject('iconservice','ui');$rows=$this->getVar('liveclassSessions',array()); ?>
<section class="liveclass-page"><header class="liveclass-page-header"><div><p class="chisimba-eyebrow"><?php echo $e($l['title']); ?></p><h1><?php echo $e($l['heading']); ?></h1><p><?php echo $e($l['intro']); ?></p></div><?php if($this->getVar('liveclassCanCreate',false)): ?><a class="button chisimba-button-primary" href="<?php echo $e($this->uri(array('action'=>'add'))); ?>"><?php echo $icons->render('plus',array('decorative'=>true)); ?><span><?php echo $e($l['add']); ?></span></a><?php endif; ?></header>
<?php if($this->getVar('liveclassMessage','')!==''): ?><p class="chisimba-notice chisimba-notice-success"><?php echo $e($this->getVar('liveclassMessage')); ?></p><?php endif; ?><?php if($this->getVar('liveclassError','')!==''): ?><p class="chisimba-notice chisimba-notice-error"><?php echo $e($this->getVar('liveclassError')); ?></p><?php endif; ?>
<div class="liveclass-grid"><?php foreach($rows as $row): ?><article class="liveclass-card"><div><span class="chisimba-status-pill"><?php echo $e($l['status_'.$row['status']]??$row['status']); ?></span><h2><?php echo $e($row['name']); ?></h2><p><?php echo $e($row['description']); ?></p></div><dl><dt><?php echo $e($l['starts']); ?></dt><dd><?php echo $e($row['starts_at']); ?></dd><dt><?php echo $e($l['duration']); ?></dt><dd><?php echo (int)$row['duration_minutes']; ?></dd></dl><a class="button chisimba-button-secondary" href="<?php echo $e($this->uri(array('action'=>'view','id'=>$row['id']))); ?>"><?php echo $icons->render('arrow-right',array('decorative'=>true)); ?><span><?php echo $e($row['name']); ?></span></a></article><?php endforeach; ?><?php if(!$rows): ?><p class="liveclass-empty"><?php echo $e($l['empty']); ?></p><?php endif; ?></div></section>
